```python
import json
import re
import pandas as pd

def task_func(json_str):
    """
    Load a JSON string into a dictionary, normalize the dictionary by doubling the numerical values,
    and then create a Pandas DataFrame from the dictionary.

    Parameters:
    json_str (str): A JSON string to process

    Returns:
    DataFrame: A pandas DataFrame created from the dictionary.
    """
    # Handle empty or invalid JSON string
    if not json_str or not json_str.strip():
        return pd.DataFrame()

    try:
        # Load JSON string into dictionary
        data_dict = json.loads(json_str)

        # If the loaded data is not a dictionary, return empty DataFrame
        if not isinstance(data_dict, dict):
            return pd.DataFrame()

        # Create a copy to avoid modifying the original during iteration
        normalized_dict = {}

        for key, value in data_dict.items():
            # Handle None values
            if value is None:
                normalized_dict[key] = value
                continue

            # Handle strings that might contain numbers
            if isinstance(value, str):
                # Try to extract numbers from the string using regex
                numbers = re.findall(r'-?\d+\.?\d*', value)
                if numbers:
                    # If numbers found, convert them to float and double
                    try:
                        # For simplicity, take the first number found
                        num = float(numbers[0])
                        normalized_dict[key] = str(num * 2)
                    except (ValueError, TypeError):
                        normalized_dict[key] = value
                else:
                    normalized_dict[key] = value

            # Handle integers and floats
            elif isinstance(value, (int, float)):
                normalized_dict[key] = value * 2

            # Handle lists
            elif isinstance(value, list):
                normalized_list = []
                for item in value:
                    if isinstance(item, (int, float)):
                        normalized_list.append(item * 2)
                    elif isinstance(item, str):
                        # Try to extract numbers from string items
                        numbers = re.findall(r'-?\d+\.?\d*', item)
                        if numbers:
                            try:
                                num = float(numbers[0])
                                normalized_list.append(str(num * 2))
                            except (ValueError, TypeError):
                                normalized_list.append(item)
                        else:
                            normalized_list.append(item)
                    else:
                        normalized_list.append(item)
                normalized_dict[key] = normalized_list

            # Handle other types (keep as-is)
            else:
                normalized_dict[key] = value

        # Create DataFrame from the normalized dictionary
        df = pd.DataFrame([normalized_dict])

        # Convert numerical columns to float where possible
        for col in df.columns:
            try:
                df[col] = pd.to_numeric(df[col], errors='ignore')
            except:
                pass

        return df

    except (json.JSONDecodeError, TypeError):
        return pd.DataFrame()
```

This function:

1. **Handles edge cases**: Returns an empty DataFrame for empty/invalid JSON or non-dictionary JSON
2. **Processes different data types**:
   - Strings: Extracts numbers using regex and doubles them
   - Numbers (int/float): Directly doubles them
   - Lists: Processes each element individually
   - Other types: Leaves them unchanged
3. **Avoids nested dictionaries**: Only processes flat dictionaries as specified
4. **Creates a DataFrame**: Converts the normalized dictionary to a pandas DataFrame
5. **Converts to numeric**: Attempts to convert numerical values to float type where possible

Example usage:
```python
json_str = '{"a": 5, "b": 3.14, "c": "10 units", "d": [1, 2, 3], "e": "text"}'
df = task_func(json_str)
print(df)
```

This would output a DataFrame with doubled numerical values where applicable.
